import{_ as i,a0 as m,w as p,s as l,I as o,x as n,a1 as r,A as s,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Linux中命令鏈接操作符的十個最佳實例 | LCTT x X-CMD","titleTemplate":false,"description":"Linux中命令鏈接操作符的十個最佳實例 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux中命令鏈接操作符的十個最佳實例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux中命令鏈接操作符的十個最佳實例 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/10 Useful Chaining Operators in Linux with Practical Examples","title":"Linux中命令鏈接操作符的十個最佳實例","tag":"201401","desc":""},"relativePath":"201401/10 Useful Chaining Operators in Linux with Practical Examples.md","filePath":"[post].md"}'),d={name:"201401/10 Useful Chaining Operators in Linux with Practical Examples.md"};function g(c,t,h,x,u,w){const e=m("Link");return p(),l("div",null,[t[26]||(t[26]=o("h1",{id:"linux中命令鏈接操作符的十個最佳實例",tabindex:"-1"},[n("Linux中命令鏈接操作符的十個最佳實例 "),o("a",{class:"header-anchor",href:"#linux中命令鏈接操作符的十個最佳實例","aria-label":"Permalink to “Linux中命令鏈接操作符的十個最佳實例”"},"​")],-1)),o("p",null,[t[1]||(t[1]=n("Linux命令中的鏈接的意思是，通過操作符的行為將幾個命令組合執行。Linux中的鏈接命令，有些像你在shell中寫",-1)),r(e,{href:"http://www.tecmint.com/category/bash-shell/"},{default:s(()=>[...t[0]||(t[0]=[n("短小的shell腳本",-1)])]),_:1}),t[2]||(t[2]=n("，並直接在終端中執行。鏈接使得自動處理變得更方便。不僅如此，一個無人看管的機器在鏈接操作符的幫助下能夠十分有條理地運行。",-1))]),t[27]||(t[27]=a(`<p><img src="http://www.tecmint.com/wp-content/uploads/2013/12/Chaining-Operators-in-Linux.png" alt="Linux中的10個鏈接操作符"></p><p><em>Linux中的10個鏈接操作符</em></p><p>本文旨在介紹一些常用的<strong>鏈接操作符</strong>，通過簡短的描述和相關的例子幫助讀者提高生產力、降低系統負載、寫出更加簡短有意義的代碼。</p><h3 id="_1-和號操作符" tabindex="-1">1. 和號操作符 (&amp;) <a class="header-anchor" href="#_1-和號操作符" aria-label="Permalink to “1. 和號操作符 (&amp;)”">​</a></h3><p>‘<strong>&amp;</strong>’的作用是使命令在後台運行。只要在命令後面跟上一個空格和 ‘<strong>&amp;</strong>’。你可以一口氣在後台運行多個命令。</p><p>在後台運行一個命令:</p><pre><code>tecmint@localhost:~$ ping ­c5 www.tecmint.com &amp;
</code></pre><p>同時在後台運行兩個命令：</p><pre><code>root@localhost:/home/tecmint# apt-get update &amp; mkdit test &amp;
</code></pre><h3 id="_2-分號操作符" tabindex="-1">2. 分號操作符 (😉 <a class="header-anchor" href="#_2-分號操作符" aria-label="Permalink to “2. 分號操作符 (”">​</a></h3><p>分號操作符使你可以一口氣運行幾個命令，命令順序執行。</p><pre><code>root@localhost:/home/tecmint# apt-get update ; apt-get upgrade ; mkdir test
</code></pre><p>上述命令先後執行了update和upgrade，最後在當前工作目錄下創建了一個‘<strong>test</strong>’文件夾</p><h3 id="_3-與操作符" tabindex="-1">3. 與操作符 (&amp;&amp;) <a class="header-anchor" href="#_3-與操作符" aria-label="Permalink to “3. 與操作符 (&amp;&amp;)”">​</a></h3><p>如果第一個命令執行成功，<strong>與操作符 (&amp;&amp;)</strong>才會執行第二個命令，也就是説，第一個命令退出狀態是<strong>0</strong>。（譯註：原文的這裏明顯寫錯了，我們進行了改譯，有興趣的讀者可以參看原文以及原文下面的評論。在UNIX裏面，0表示無錯誤，而所有非0返回值都是各種錯誤）。這個命令在檢查最後一個命令的執行狀態時很有用。</p>`,15)),o("p",null,[t[4]||(t[4]=n("比如，我想使用",-1)),o("strong",null,[r(e,{href:"http://www.tecmint.com/command-line-web-browsers/"},{default:s(()=>[...t[3]||(t[3]=[n("links 命令",-1)])]),_:1})]),t[5]||(t[5]=n("在終端中訪問網站",-1)),t[6]||(t[6]=o("strong",null,"tecmint.com",-1)),t[7]||(t[7]=n("，但在這之前我需要檢查主機是否",-1)),t[8]||(t[8]=o("strong",null,"在線",-1)),t[9]||(t[9]=n("或",-1)),t[10]||(t[10]=o("strong",null,"不在線",-1)),t[11]||(t[11]=n("。",-1))]),t[28]||(t[28]=a(`<pre><code>root@localhost:/home/tecmint# ping -c3 www.tecmint.com &amp;&amp; links www.tecmint.com
</code></pre><h3 id="_4-或操作符" tabindex="-1">4. 或操作符 (||) <a class="header-anchor" href="#_4-或操作符" aria-label="Permalink to “4. 或操作符 (||)”">​</a></h3><p><strong>或操作符 (||)</strong>很像編程中的<strong>else</strong>語句。上面的操作符允許你在第一個命令失敗的情況下執行第二個命令，比如，第一個命令的退出狀態是<strong>1</strong>。</p><p>舉例來説，我想要在非root帳户中執行‘<strong>apt-get update</strong>‘，如果第一個命令失敗了，接着會執行第二個命令‘<strong>links www.tecmint.com</strong>‘。</p><pre><code>tecmint@localhost:~$ apt-get update || links tecmint.com
</code></pre><p>上面的命令中，由於該<strong>用户</strong>不允許<strong>更新</strong>系統，這意味着第一個命令的退出狀態是’<strong>1</strong>′,因此最後一個命令‘<strong>links tecmint.com</strong>‘會執行。</p><p>如果第一個命令成功執行並且退出狀態是‘<strong>0</strong>‘呢？很明顯的，第二個命令不會執行。</p><pre><code>tecmint@localhost:~$ mkdir test || links tecmint.com
</code></pre><p>這裏，用户在家目錄創建了一個‘<strong>test</strong>‘文件夾，這是被允許的。命令成功的執行，退出狀態是‘<strong>0</strong>‘,因此，最後的命令不會執行。</p><h3 id="_5-非操作符" tabindex="-1">5. 非操作符 (!) <a class="header-anchor" href="#_5-非操作符" aria-label="Permalink to “5. 非操作符 (!)”">​</a></h3><p><strong>非操作符 (!)</strong>很像<strong>except</strong>語句。這個命令會執行除了提供的條件外的所有的語句。要理解這點，在你的主目錄創建一個目錄‘<strong>tecmint</strong>’，並‘<strong>cd</strong>’到它這裏。</p><pre><code>tecmint@localhost:~$ mkdir tecmint 
tecmint@localhost:~$ cd tecmint
</code></pre><p>接下來，在文件夾‘<strong>tecmint</strong>’下創建不同類型的文件。</p><pre><code>tecmint@localhost:~/tecmint$ touch a.doc b.doc a.pdf b.pdf a.xml b.xml a.html b.html
</code></pre><p>看一下我們在文件夾‘<strong>tecmint</strong>’創建的新文件。</p><pre><code>tecmint@localhost:~/tecmint$ ls 

a.doc  a.html  a.pdf  a.xml  b.doc  b.html  b.pdf  b.xml
</code></pre><p>用一種聰明的辦法馬上刪除除了 ‘<strong>html</strong>’之外的所有文件。</p><pre><code>tecmint@localhost:~/tecmint$ rm -r !(*.html)
</code></pre>`,18)),o("p",null,[t[13]||(t[13]=n("驗證一下上次的執行結果，使用",-1)),r(e,{href:"http://www.tecmint.com/15-basic-ls-command-examples-in-linux/"},{default:s(()=>[...t[12]||(t[12]=[n("ls 命令",-1)])]),_:1}),t[14]||(t[14]=n("列出可見所有文件。",-1))]),t[29]||(t[29]=a(`<pre><code>tecmint@localhost:~/tecmint$ ls 

a.html  b.html
</code></pre><h3 id="_6-與或操作符-–" tabindex="-1">6. 與或操作符 (&amp;&amp; – ||) <a class="header-anchor" href="#_6-與或操作符-–" aria-label="Permalink to “6. 與或操作符 (&amp;&amp; – ||)”">​</a></h3><p>上面的操作符實際上是‘<strong>與</strong>’和‘<strong>或</strong>’操作符的組合。它很像‘<strong>if-else</strong>‘語句。</p><p>比如，我們ping <strong>tecmint.com</strong>，如果成功打印‘<strong>已驗證</strong>’，否則打印‘<strong>主機故障</strong>’。</p><pre><code>tecmint@localhost:~/tecmint$ ping -c3 www.tecmint.com &amp;&amp; echo &quot;Verified&quot; || echo &quot;Host Down&quot;
</code></pre><h4 id="示例輸出" tabindex="-1">示例輸出 <a class="header-anchor" href="#示例輸出" aria-label="Permalink to “示例輸出”">​</a></h4><pre><code>PING www.tecmint.com (212.71.234.61) 56(84) bytes of data. 
64 bytes from www.tecmint.com (212.71.234.61): icmp_req=1 ttl=55 time=216 ms 
64 bytes from www.tecmint.com (212.71.234.61): icmp_req=2 ttl=55 time=224 ms 
64 bytes from www.tecmint.com (212.71.234.61): icmp_req=3 ttl=55 time=226 ms 

--- www.tecmint.com ping statistics --- 
3 packets transmitted, 3 received, 0% packet loss, time 2001ms 
rtt min/avg/max/mdev = 216.960/222.789/226.423/4.199 ms 
Verified
</code></pre><p>現在，斷開我們現在的網絡連接誒，再試一下相同的命令。</p><pre><code>tecmint@localhost:~/tecmint$ ping -c3 www.tecmint.com &amp;&amp; echo &quot;verified&quot; || echo &quot;Host Down&quot;
</code></pre><h4 id="實例輸出" tabindex="-1">實例輸出 <a class="header-anchor" href="#實例輸出" aria-label="Permalink to “實例輸出”">​</a></h4><pre><code>ping: unknown host www.tecmint.com 
Host Down
</code></pre><h3 id="_7-管道操作符" tabindex="-1">7. 管道操作符 (|) <a class="header-anchor" href="#_7-管道操作符" aria-label="Permalink to “7. 管道操作符 (|)”">​</a></h3><p><strong>PIPE</strong>在將第一個命令的輸出作為第二個命令的輸入時很有用。比如，‘<strong>ls -l</strong>’的輸出通過管道到‘<strong>less</strong>’，並看一下輸出。</p><pre><code>tecmint@localhost:~$ ls -l | less
</code></pre><h3 id="_8-命令合併操作符" tabindex="-1">8. 命令合併操作符 {} <a class="header-anchor" href="#_8-命令合併操作符" aria-label="Permalink to “8. 命令合併操作符 {}”">​</a></h3><p>合併兩個或多個命令，第二個命令依賴於第一個命令的執行。</p><p>比如，檢查一下文件‘<strong>xyz.txt</strong>’是否在<strong>Downloads</strong>目錄下，如果不存在則創建之並輸出提示信息。</p><pre><code>tecmint@localhost:~$ [ -f /home/tecmint/Downloads/xyz.txt ] || touch /home/tecmint/Downloads/xyz.txt; echo &quot;The file does not exist&quot;
</code></pre><p>但是這樣的命令的運行結果並不如我們預期的運行，會始終都輸出提示信息。因此需要使用{}操作符來合併命令：</p><pre><code>tecmint@localhost:~$ [ -f /home/tecmint/Downloads/xyz1.txt ] || {touch /home/tecmint/Downloads/xyz.txt; echo &quot;The file does not exist&quot;}

“The file does not exist”
</code></pre><p>（譯註：原文這裏應該也是複製或書寫的時候，出現了一些問題，例子中並沒有出現小標題中的&quot;{}&quot;操作符，所以這裏我們進行了修改）</p><h3 id="_9-優先操作符" tabindex="-1">9. 優先操作符 () <a class="header-anchor" href="#_9-優先操作符" aria-label="Permalink to “9. 優先操作符 ()”">​</a></h3><p>這個操作符可以讓命令以優先順序執行。</p><pre><code>Command_x1 &amp;&amp;Command_x2 || Command_x3 &amp;&amp; Command_x4.
</code></pre><p>在上面的偽代碼中，如果<strong>Command_x1</strong>執行失敗了會怎麼樣，<strong>Command_x2</strong>, <strong>Command_x3</strong>, <strong>Command_x4</strong>沒有一個會執行，對於這種情況，我們使用<strong>優先操作符</strong>。</p><pre><code>(Command_x1 &amp;&amp;Command_x2) || (Command_x3 &amp;&amp; Command_x4)
</code></pre><p>在上面的偽代碼中，如果<strong>Command_x1</strong>執行失敗，<strong>Command_x2</strong>不會執行，但是<strong>Command_x3</strong>會繼續執行， <strong>Command_x4</strong>會依賴於 <strong>Command_x3</strong>的退出狀態。</p><h3 id="_10-連接符" tabindex="-1">10. 連接符 () <a class="header-anchor" href="#_10-連接符" aria-label="Permalink to “10. 連接符 ()”">​</a></h3><p><strong>連接符 ()</strong>如它名字所説，被用於連接shell中那些太長而需要分成多行的命令。可以在輸入一個“\\”之後就回車，然後繼續輸入命令列，直到輸入完成。比如，下面的命令會打開文本文件<strong>test(1).txt</strong>。</p><pre><code>tecmint@localhost:~/Downloads$ nano test\\
1.txt
</code></pre><p>今天就到這裏，我會近日開始另外一個有趣的文章。不要走開，繼續關注<strong>Tecmint</strong>。不要忘記在評論欄裏提出有價值的反饋。</p><hr>`,32)),o("p",null,[t[16]||(t[16]=n("via: ",-1)),r(e,{href:"http://www.tecmint.com/chaining-operators-in-linux-with-practical-examples/"},{default:s(()=>[...t[15]||(t[15]=[n("http://www.tecmint.com/chaining-operators-in-linux-with-practical-examples/",-1)])]),_:1})]),o("p",null,[t[19]||(t[19]=n("譯者：",-1)),r(e,{href:"https://github.com/geekpi"},{default:s(()=>[...t[17]||(t[17]=[n("geekpi",-1)])]),_:1}),t[20]||(t[20]=n(" 校對：",-1)),r(e,{href:"http://blog.csdn.net/tinyeyeser"},{default:s(()=>[...t[18]||(t[18]=[n("Mr小眼兒",-1)])]),_:1})]),o("p",null,[t[23]||(t[23]=n("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[21]||(t[21]=[n("LCTT",-1)])]),_:1}),t[24]||(t[24]=n(" 原創翻譯，",-1)),r(e,{href:"http://linux.cn/"},{default:s(()=>[...t[22]||(t[22]=[n("Linux中國",-1)])]),_:1}),t[25]||(t[25]=n(" 榮譽推出",-1))])])}const C=i(d,[["render",g]]);export{_ as __pageData,C as default};
